  document_id:=null;
  insert into public.cms_documents(module_id,entity_key,draft) values(item->>'moduleId',item->>'key',item->'payload') on conflict(module_id,entity_key) do nothing returning id into document_id;
  if document_id is not null then
   insert into public.cms_versions(document_id,version_number,schema_version,snapshot,created_by,origin) values(document_id,1,1,item->'payload',null,'import');
   update public.cms_documents set state='published',published_version=1 where id=document_id;
   insert into public.cms_audit_logs(actor_id,actor_kind,action,entity_type,entity_id,metadata) values(null,'migration','IMPORT',item->>'moduleId',document_id,jsonb_build_object('source','approved-local-catalog','migration','cms_import_approved_catalog_v1','databaseActor',current_user));
  end if;
 end loop;
end; $import$;
-- Separate team/public read policies; anon never invokes an authenticated-only helper.
alter policy cms_media_read on storage.objects to anon using(bucket_id='cms-media' and cms_private.media_published(name));
create policy cms_media_team_read on storage.objects for select to authenticated using(bucket_id='cms-media' and (cms_private.media_published(name) or cms_private.can_perform('media')));
